liveness_template:
(() => {
  window.__livenessUploadMode = "__UPLOAD_MODE__";
  window.__livenessStepMs = __STEP_MS__;
  window.__livenessStepJitterMs = __STEP_JITTER_MS__;
  window.__livenessTimeline = __TIMELINE_JSON__;
  window.__livenessRecordStart = null;
  window.__livenessNextAdvanceIdx = 1;

  function normalizeTimelinePos(position) {
    return String(position || "center").toLowerCase();
  }

  function mapTimelineToSitePos(timelinePos, sitePositions) {
    const key = normalizeTimelinePos(timelinePos);
    const aliases = {
      center: ["init", "center"],
      left: ["left"],
      right: ["right"],
      up: ["up"],
      down: ["down"],
    };
    const wanted = aliases[key] || [key];
    const match = (sitePositions || []).find((pos) =>
      wanted.includes(String(pos || "").toLowerCase())
    );
    return match || sitePositions?.[0] || key;
  }

  function getTimelineElapsedMs() {
    if (typeof window.__getVirtualCameraPlaybackMs === "function") {
      const playbackMs = window.__getVirtualCameraPlaybackMs();
      if (playbackMs > 0 || window.__livenessRecordStart) {
        return playbackMs;
      }
    }
    return window.__livenessRecordStart
      ? Math.max(0, Date.now() - window.__livenessRecordStart)
      : 0;
  }

  function getTimelineEndMs() {
    const timeline = window.__livenessTimeline || [];
    let endMs = 16000;
    if (timeline.length) {
      const last = timeline[timeline.length - 1];
      const prev = timeline[timeline.length - 2];
      const segmentMs = prev ? Math.max(1000, last.startMs - prev.startMs) : 3000;
      endMs = last.startMs + segmentMs;
    }
    if (typeof window.__getVirtualCameraDurationMs === "function") {
      const durationMs = window.__getVirtualCameraDurationMs();
      if (durationMs > 0) {
        endMs = Math.min(endMs, durationMs);
      }
    }
    return endMs;
  }

  async function syncTimelineToVideoStart() {
    if (typeof window.__resetVirtualCameraForLiveness === "function") {
      await window.__resetVirtualCameraForLiveness();
    }
    resetTimelineRecording();
  }

  function resetTimelineRecording() {
    window.__livenessNextAdvanceIdx = 1;
    window.__currentPos = null;
    window.__stepStartTime = Date.now();
    window.__livenessRecordStart = Date.now();
  }

  function getTimelineSegment(elapsedMs) {
    const timeline = window.__livenessTimeline || [];
    let segment = timeline[0] || { startMs: 0, position: "center" };
    for (const mark of timeline) {
      if (elapsedMs >= mark.startMs) segment = mark;
      else break;
    }
    return segment;
  }

  function applyTimelineTimecodes(rc) {
    const timeline = window.__livenessTimeline || [];
    const start = window.__livenessRecordStart;
    if (!start || !timeline.length || !rc?.timecodes) return;
    rc.timecodes.clear();
    const positions = rc.deps?.positions?.() || [];
    let previous = null;
    for (const mark of timeline) {
      const pos = mapTimelineToSitePos(mark.position, positions);
      const normalized = String(pos || "").toLowerCase();
      const prevNorm = String(previous || "").toLowerCase();
      if (pos && normalized !== prevNorm) {
        rc.timecodes.add([pos, start + mark.startMs]);
        previous = pos;
      }
    }
  }

  function buildLandmarks(position) {
    const landmarks = Array.from({ length: 478 }, () => ({ x: 0.5, y: 0.5, z: 0 }));
    const pos = String(position || "").toLowerCase();
    let yaw = 0;
    let pitch = 0;
    if (pos.includes("left")) yaw = -0.14;
    else if (pos.includes("right")) yaw = 0.14;
    if (pos.includes("up")) pitch = -0.1;
    else if (pos.includes("down")) pitch = 0.1;
    for (const index of [33, 263, 1, 61, 291, 199]) {
      if (!landmarks[index]) continue;
      landmarks[index].x = Math.min(0.95, Math.max(0.05, 0.5 + yaw));
      landmarks[index].y = Math.min(0.95, Math.max(0.05, 0.5 + pitch));
    }
    return landmarks;
  }

  function mockLandmarkerInstance(getPosition) {
    return {
      detectForVideo: () => ({ faceLandmarks: [buildLandmarks(getPosition?.())] }),
      detect: () => ({ faceLandmarks: [buildLandmarks(getPosition?.())] }),
      close: () => {},
    };
  }

  function patchFaceLandmarker(flm, getPosition) {
    if (!flm || flm.__automationPatched) return;
    flm.__automationPatched = true;
    flm.ready = true;
    flm.error = false;
    flm.get = () => mockLandmarkerInstance(getPosition);
    flm.isReady = () => true;
    flm.hasError = () => false;
    flm.load = () => Promise.resolve(flm.get());
    flm.loadRaw = () => Promise.resolve(flm.get());
    try { flm.emitStateChange?.(); } catch (_) {}
  }

  function enableProceedButton() {
    const btn = document.getElementById("btn-video-instructions-proceed");
    if (btn) {
      btn.disabled = false;
      btn.removeAttribute("disabled");
      btn.setAttribute("aria-busy", "false");
    }
    const preparing = document.getElementById("video-instructions-preparing");
    if (preparing) preparing.style.display = "none";
    const spinner = document.getElementById("video-instructions-proceed-spinner");
    if (spinner) spinner.style.display = "none";
  }

  function patchVisionController(vc, getPosition) {
    if (!vc) return;
    vc.ready = true;
    vc.error = false;
    vc.loading = false;
    vc.loadProgress = 100;
    vc.isReady = () => true;
    vc.hasError = () => false;
    vc.load = () => Promise.resolve();
    vc.get = () => {
      const pos = getPosition ? String(getPosition() || "center").toLowerCase() : "center";
      const isLeft = pos.includes("left");
      const isRight = pos.includes("right");
      const isCenter = !isLeft && !isRight;
      return {
        setFrame: async () => {},
        frame: {
          hasFace: true,
          isCenter: isCenter,
          isLeft: isLeft,
          isRight: isRight,
          rotation: { yaw: isLeft ? -0.2 : (isRight ? 0.2 : 0), pitch: 0, roll: 0 },
        },
      };
    };
    try {
      if (vc.stateListeners) {
        vc.stateListeners.forEach((fn) => { try { fn(); } catch (_) {} });
      }
    } catch (_) {}
  }

  function patchInstructionsController(ic) {
    if (!ic || ic.__automationPatched) return;
    ic.__automationPatched = true;
    ic.isProceedDisabled = () => false;
    ic.shouldShowProceedLoader = () => false;
    if (ic.deps?.visionController) {
      patchVisionController(ic.deps.visionController, () => "center");
      try { ic.syncVisionUi?.(); } catch (_) {}
    }
    ic.syncProceedState = function() {
      patchFaceLandmarker(this.deps?.faceLandmarker?.(), () => null);
      if (this.deps?.visionController) {
        patchVisionController(this.deps.visionController, () => "center");
        try { this.syncVisionUi?.(); } catch (_) {}
      }
      this.view?.refreshProceedState?.(false, false);
      enableProceedButton();
    };
    ic.syncProceedState();
  }

  function patchRecordController(rc) {
    if (!rc || rc.__automationPatched) return;
    rc.__automationPatched = true;

    rc.syncFaceLandmarkerReady = function() {
      this.faceLandmarkerReady = true;
      this.recordView?.setFaceLandmarkerReady?.(true);
    };
    rc.syncFaceLandmarkerReady();
    rc.setHasFace(true);

    const getPosition = () => {
      const elapsed = getTimelineElapsedMs();
      const segment = getTimelineSegment(elapsed);
      const positions = rc.deps?.positions?.() || [];
      return mapTimelineToSitePos(segment.position, positions);
    };
    patchFaceLandmarker(rc.deps?.faceLandmarker?.(), getPosition);
    if (rc.deps?.visionController) {
      patchVisionController(rc.deps.visionController, getPosition);
    }
    if (rc.headPositionGuide && !rc.headPositionGuide.__automationPatched) {
      rc.headPositionGuide.__automationPatched = true;
      rc.headPositionGuide.checkHead = function(targetPos, frame) {
        if (!window.__livenessRecordStart) {
          resetTimelineRecording();
        }
        const elapsed = getTimelineElapsedMs();
        const timeline = window.__livenessTimeline || [];
        const idx = window.__livenessNextAdvanceIdx || 1;
        const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
        const advance = elapsed >= targetMs;
        const currentTarget = String(targetPos || "center").toLowerCase();
        const curPos = String(getPosition?.() || "center").toLowerCase();
        const matched = curPos.includes(currentTarget) || (currentTarget === "center" && !curPos.includes("left") && !curPos.includes("right"));
        const passed = advance && matched;
        return {
          kind: currentTarget === "center" ? 1 : 2,
          status: passed ? 1 : 2,
          passed: passed,
        };
      };
    }

    rc.decider = rc.decider || {};
    rc.decider.decide = function(data) {
      if (!window.__livenessRecordStart) {
        resetTimelineRecording();
      }
      const elapsed = getTimelineElapsedMs();
      const timeline = window.__livenessTimeline || [];
      const idx = window.__livenessNextAdvanceIdx || 1;
      const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
      const advance = elapsed >= targetMs;
      const pos = String(data.position || "").toLowerCase();
      const isSide = pos.includes("left") || pos.includes("right");
      if (!isSide) {
        return { kind: "all", status: "success", advance };
      }
      return {
        kind: "side",
        position: data.position,
        status: "success",
        advance,
      };
    };

    if (typeof rc.goToNextPosition === "function" && !rc.__goNextPatched) {
      rc.__goNextPatched = true;
      const originalGoNext = rc.goToNextPosition.bind(rc);
      rc.goToNextPosition = async function() {
        window.__livenessNextAdvanceIdx = (window.__livenessNextAdvanceIdx || 1) + 1;
        return originalGoNext();
      };
    }

    rc.getAudio = () => ({
      isAudioPlaying: () => false,
      stop: () => {},
      play: () => Promise.resolve(),
    });

    const originalStop = rc.stopRecord?.bind(rc);
    if (originalStop) {
      rc.stopRecord = async function() {
        await new Promise((resolve) => setTimeout(resolve, 3500));
        return originalStop();
      };
    }

    rc.shouldProcessFrame = function() {
      return !this.disposed && !this.showTryAgainUi && !this.isFinished();
    };

    if (typeof rc.onFrame === "function") {
      const oldOnFrame = rc.onFrame.bind(rc);
      rc.onFrame = async function() {
        this.setHasFace(true);
        await oldOnFrame();
      };
    }

    if (typeof rc.initRecordSession === "function") {
      const originalInit = rc.initRecordSession.bind(rc);
      rc.initRecordSession = async function(args) {
        const playbackMs =
          typeof window.__getVirtualCameraPlaybackMs === "function"
            ? window.__getVirtualCameraPlaybackMs()
            : 0;
        if (!window.__livenessRecordStart || playbackMs < 500) {
          await syncTimelineToVideoStart();
        } else {
          resetTimelineRecording();
        }
        this.syncFaceLandmarkerReady();
        this.setHasFace(true);
        return originalInit(args);
      };
    }

    if (typeof rc.uploadRecordedVideo === "function" && !rc.__uploadSwapPatched) {
      rc.__uploadSwapPatched = true;
      const originalUpload = rc.uploadRecordedVideo.bind(rc);
      rc.uploadRecordedVideo = async function() {
        if (window.__livenessUploadMode === "file3_swap") {
          applyTimelineTimecodes(this);
        }
        window.__restoreVirtualCameraLoop?.();
        const recorder = this.session.getRecorder();
        if (!recorder) {
          console.error("[AUTOMATION] uploadRecordedVideo: no recorder");
          this.recordedUploadFailed?.();
          return;
        }
        if (window.__livenessUploadMode !== "file3_swap") {
          return originalUpload.call(this);
        }
        await recorder.stop();
        const slot = window.__livenessUploadSlot ?? 2;
        const swapFile = await window.__fetchVirtualCameraFile?.(slot);
        if (!swapFile) {
          console.error("[AUTOMATION] uploadRecordedVideo: File 3 source missing");
          this.recordedUploadFailed?.();
          return;
        }
        window.__lastLivenessUploadFile = swapFile.name;
        const originalGetBlob = recorder.getBlob.bind(recorder);
        const originalGetMime = recorder.getRecordedMimeType.bind(recorder);
        recorder.getBlob = () => swapFile;
        recorder.getRecordedMimeType = () => swapFile.type || "video/mp4";
        try {
          return await originalUpload.call(this);
        } finally {
          recorder.getBlob = originalGetBlob;
          recorder.getRecordedMimeType = originalGetMime;
        }
      };
    }

    setTimeout(() => {
      try {
        const surface = rc.getCaptureSurfaceFromView?.();
        if (surface && rc.onWebcamError && !rc.getRecordStream?.()) {
          rc.initRecordSession({ ...surface, onWebcamError: rc.onWebcamError });
        }
      } catch (err) {
        console.warn("[AUTOMATION] initRecordSession retry failed", err);
      }
    }, 800);
  }

  function patchVideoController(ctrl) {
    if (!ctrl || ctrl.__automationVideoPatched) return;
    ctrl.__automationVideoPatched = true;
    window.__activeVideoController = ctrl;

    patchFaceLandmarker(ctrl.faceLandmarker, () => {
      const rc = ctrl.recordController;
      if (!rc) return null;
      const elapsed = getTimelineElapsedMs();
      const segment = getTimelineSegment(elapsed);
      const positions = rc.deps?.positions?.() || [];
      return mapTimelineToSitePos(segment.position, positions);
    });
    if (ctrl.visionController) {
      patchVisionController(ctrl.visionController, () => "center");
    }
    patchInstructionsController(ctrl.instructionsController);
    enableProceedButton();

    if (ctrl.instructionsController?.view) {
      ctrl.instructionsController.view.refreshProceedState?.(false, false);
    }
    if (ctrl.recordController) {
      patchRecordController(ctrl.recordController);
    }
  }

  function hook() {
    if (typeof VerificationWizardVideo === "undefined") return;

    if (!VerificationWizardVideo.__controllerWrapped) {
      VerificationWizardVideo.__controllerWrapped = true;
      const Original = VerificationWizardVideo.StepVideoController;
      const Wrapped = function(...args) {
        const instance = new Original(...args);
        patchVideoController(instance);
        return instance;
      };
      Wrapped.prototype = Original.prototype;
      VerificationWizardVideo.StepVideoController = Wrapped;
    }

    const proto = VerificationWizardVideo.StepVideoController.prototype;
    if (!proto.__automationProtoPatched) {
      proto.__automationProtoPatched = true;

      const wrap = (name, after) => {
        const original = proto[name];
        if (typeof original !== "function") return;
        proto[name] = function(...args) {
          const result = original.apply(this, args);
          patchVideoController(this);
          after?.call(this, args, result);
          return result;
        };
      };

      wrap("start");
      wrap("showInstructionsPhase", function() {
        patchInstructionsController(this.instructionsController);
        enableProceedButton();
      });
      wrap("showRecordPhase", function() {
        patchRecordController(this.recordController);
      });
      wrap("showRecord");
    }

    if (window.__activeVideoController) {
      patchVideoController(window.__activeVideoController);
    }
  }

  window.__forceLivenessProceed = () => {
    hook();
    enableProceedButton();
    const ctrl = window.__activeVideoController;
    if (ctrl?.instructionsController) {
      patchInstructionsController(ctrl.instructionsController);
    }
    if (ctrl?.showRecord) {
      try {
        ctrl.showRecord();
        return "showRecord";
      } catch (err) {
        console.warn("[AUTOMATION] showRecord failed", err);
      }
    }
    if (ctrl?.showRecordPhase) {
      try {
        ctrl.showRecordPhase();
        return "showRecordPhase";
      } catch (err) {
        console.warn("[AUTOMATION] showRecordPhase failed", err);
      }
    }
    const btn = document.getElementById("btn-video-instructions-proceed");
    if (btn) {
      btn.disabled = false;
      btn.removeAttribute("disabled");
      btn.click();
      return "button-click";
    }
    return "no-controller";
  };

  window.__forceLivenessSubmit = async () => {
    hook();
    const submitController = window.__activeVideoController?.submitController;
    if (submitController?.submit) {
      await submitController.submit();
      return "submit-controller";
    }
    const btn = document.getElementById("btn-video-submit-proceed");
    if (!btn) return "missing-button";
    if (btn.disabled) return "button-disabled";
    btn.click();
    return "button-click";
  };

  if (!window.__livenessBypassHooked) {
    window.__livenessBypassHooked = true;
  }
  hook();
})();

video_step_template:
(() => {
  if (window.__videoStepNativeInstalled) return;
  window.__videoStepNativeInstalled = true;

  window.__livenessUploadMode = "__UPLOAD_MODE__";
  window.__livenessUploadSlot = 2;
  window.__livenessTimeline = __TIMELINE_JSON__;
  window.__livenessRecordStart = null;
  window.__livenessNextAdvanceIdx = 1;

  const PANEL = {
    INSTRUCTIONS: "video-panel-instructions",
    RECORD: "video-panel-record",
    SUBMIT: "video-panel-submit",
  };
  const BTN = {
    PROCEED: "btn-video-instructions-proceed",
    SUBMIT: "btn-video-submit-proceed",
  };

  const panelVisible = (id) => {
    const el = document.getElementById(id);
    if (!el) return false;
    const s = window.getComputedStyle(el);
    return s.display !== "none" && s.visibility !== "hidden";
  };

  const detectPhase = () => {
    if (panelVisible(PANEL.SUBMIT)) return "submit";
    if (panelVisible(PANEL.RECORD)) return "record";
    if (panelVisible(PANEL.INSTRUCTIONS)) return "instructions";
    const submitBtn = document.getElementById(BTN.SUBMIT);
    if (submitBtn) {
      const s = window.getComputedStyle(submitBtn);
      if (s.display !== "none" && s.visibility !== "hidden") return "submit";
    }
    return "unknown";
  };

  const normalizeTimelinePos = (position) => String(position || "center").toLowerCase();

  const mapTimelineToSitePos = (timelinePos, sitePositions) => {
    const key = normalizeTimelinePos(timelinePos);
    const aliases = {
      center: ["init", "center"],
      left: ["left"],
      right: ["right"],
      up: ["up"],
      down: ["down"],
    };
    const wanted = aliases[key] || [key];
    const match = (sitePositions || []).find((pos) =>
      wanted.includes(String(pos || "").toLowerCase())
    );
    return match || sitePositions?.[0] || key;
  };

  const getTimelineElapsedMs = () => {
    if (typeof window.__getVirtualCameraPlaybackMs === "function") {
      const playbackMs = window.__getVirtualCameraPlaybackMs();
      if (playbackMs > 0 || window.__livenessRecordStart) return playbackMs;
    }
    return window.__livenessRecordStart
      ? Math.max(0, Date.now() - window.__livenessRecordStart)
      : 0;
  };

  const getTimelineEndMs = () => {
    const timeline = window.__livenessTimeline || [];
    let endMs = 13000;
    if (timeline.length) {
      const last = timeline[timeline.length - 1];
      const prev = timeline[timeline.length - 2];
      const segmentMs = prev ? Math.max(1000, last.startMs - prev.startMs) : 3000;
      endMs = last.startMs + segmentMs;
    }
    if (typeof window.__getVirtualCameraDurationMs === "function") {
      const durationMs = window.__getVirtualCameraDurationMs();
      if (durationMs > 0) endMs = Math.min(endMs, durationMs);
    }
    return endMs;
  };

  const resetTimelineRecording = () => {
    window.__livenessNextAdvanceIdx = 1;
    window.__livenessRecordStart = Date.now();
  };

  const syncTimelineToVideoStart = async () => {
    if (typeof window.__resetVirtualCameraForLiveness === "function") {
      await window.__resetVirtualCameraForLiveness();
    }
    resetTimelineRecording();
  };

  const buildLandmarks = (position) => {
    const landmarks = Array.from({ length: 478 }, () => ({ x: 0.5, y: 0.5, z: 0 }));
    const pos = String(position || "").toLowerCase();
    let yaw = 0;
    if (pos.includes("left")) yaw = -0.14;
    else if (pos.includes("right")) yaw = 0.14;
    for (const index of [33, 263, 1, 61, 291, 199]) {
      if (!landmarks[index]) continue;
      landmarks[index].x = Math.min(0.95, Math.max(0.05, 0.5 + yaw));
      landmarks[index].y = 0.5;
    }
    return landmarks;
  };

  const patchVisionController = (vc) => {
    if (!vc || vc.__nativeAutoPatched) return;
    vc.__nativeAutoPatched = true;
    const mockEngine = {
      frame: { hasFace: true, isCenter: true, isLeft: true, isRight: true },
      setFrame: async () => {},
      hasFace: () => true,
      getFrame: () => ({ hasFace: true, isCenter: true, isLeft: true, isRight: true }),
      bindVideo: () => {},
      unbindVideo: () => {},
      getInferEveryNFrames: () => 5,
      getProviderId: () => "native",
      close: () => {},
    };
    vc.isReady = () => true;
    vc.hasError = () => false;
    vc.get = () => mockEngine;
    vc.load = () => Promise.resolve();
    vc.loadRaw = () => Promise.resolve();
    vc.ensureReady = () => Promise.resolve();
    vc.switchToFallback = () => {};
    vc.hasFallbackAvailable = () => false;
    try { vc.emitStateChange?.(); } catch (_) {}
  };

  const patchFaceLandmarker = (flm, getPosition) => {
    if (!flm || flm.__nativeAutoPatched) return;
    flm.__nativeAutoPatched = true;
    const mock = {
      detectForVideo: () => ({ faceLandmarks: [buildLandmarks(getPosition?.())] }),
      detect: () => ({ faceLandmarks: [buildLandmarks(getPosition?.())] }),
      close: () => {},
    };
    flm.ready = true;
    flm.error = false;
    flm.get = () => mock;
    flm.isReady = () => true;
    flm.hasError = () => false;
    flm.load = () => Promise.resolve(mock);
    flm.loadRaw = () => Promise.resolve(mock);
    try { flm.emitStateChange?.(); } catch (_) {}
  };

  const enableProceedButton = () => {
    const btn = document.getElementById(BTN.PROCEED);
    if (btn) {
      btn.disabled = false;
      btn.removeAttribute("disabled");
      btn.setAttribute("aria-busy", "false");
    }
    const preparing = document.getElementById("video-instructions-preparing");
    if (preparing) preparing.style.display = "none";
    const spinner = document.getElementById("video-instructions-proceed-spinner");
    if (spinner) spinner.style.display = "none";
  };

  const patchInstructionsController = (ic) => {
    if (!ic || ic.__nativeAutoPatched) return;
    ic.__nativeAutoPatched = true;
    ic.isProceedDisabled = () => false;
    ic.shouldShowProceedLoader = () => false;
    if (ic.deps?.visionController) {
      patchVisionController(ic.deps.visionController);
    }
    const unblockView = (view) => {
      if (!view) return;
      view.proceedDisabled = false;
      view.instructionsContentReady = true;
      if (typeof view.refreshVisionUi === "function" && !view.__nativeRefreshPatched) {
        view.__nativeRefreshPatched = true;
        const origRefresh = view.refreshVisionUi.bind(view);
        view.refreshVisionUi = function (opts) {
          try { origRefresh(opts); } catch (_) {}
          this.proceedDisabled = false;
          enableProceedButton();
        };
      }
    };
    unblockView(ic.view);
    ic.syncProceedState = function () {
      patchFaceLandmarker(this.deps?.faceLandmarker?.(), () => null);
      if (this.deps?.visionController) patchVisionController(this.deps.visionController);
      this.view?.refreshProceedState?.(false, false);
      unblockView(this.view);
      enableProceedButton();
    };
    ic.syncProceedState();
    enableProceedButton();
  };

  const patchRecordController = (rc) => {
    if (!rc || rc.__nativeAutoPatched) return;
    rc.__nativeAutoPatched = true;

    if (rc.deps?.visionController) {
      patchVisionController(rc.deps.visionController);
    }

    rc.isRecordingWarmupComplete = () => true;

    rc.syncFaceLandmarkerReady = function () {
      this.faceLandmarkerReady = true;
      this.recordView?.setFaceLandmarkerReady?.(true);
    };
    try { rc.syncFaceLandmarkerReady(); } catch (_) {}
    try { rc.setHasFace?.(true); } catch (_) {}
    rc.hasFace = true;

    const getPosition = () => {
      const elapsed = getTimelineElapsedMs();
      const timeline = window.__livenessTimeline || [];
      let segment = timeline[0] || { startMs: 0, position: "center" };
      for (const mark of timeline) {
        if (elapsed >= mark.startMs) segment = mark;
        else break;
      }
      const rawPositions = rc.deps?.positions;
      const positions = Array.isArray(rawPositions)
        ? rawPositions
        : (typeof rawPositions === "function" ? rawPositions() : []);
      return mapTimelineToSitePos(segment.position, positions);
    };

    if (rc.deps?.faceLandmarker) {
      patchFaceLandmarker(rc.deps.faceLandmarker?.(), getPosition);
    }

    // Support headPositionGuide (Source file / latest AgeSmart architecture)
    if (rc.headPositionGuide && !rc.headPositionGuide.__nativeAutoPatched) {
      rc.headPositionGuide.__nativeAutoPatched = true;
      rc.headPositionGuide.applyHeadCheck = function (position, frame) {
        if (typeof this.stopFlashing === "function") this.stopFlashing();
        const pos = String(position || "CENTER").toUpperCase();
        const elapsed = getTimelineElapsedMs();
        const timeline = window.__livenessTimeline || [];
        const idx = window.__livenessNextAdvanceIdx || 1;
        const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
        const advance = elapsed >= targetMs || elapsed >= getTimelineEndMs();
        const isCenter = pos === "CENTER";
        const kind = isCenter ? "all" : "side";
        const result = {
          kind: kind,
          status: "success",
          passed: advance,
          position: position,
        };
        try {
          this.getView?.()?.applyHeadCheckResult?.(result);
        } catch (_) {}
        return result;
      };

      if (typeof rc.headPositionGuide.checkHead === "function") {
        rc.headPositionGuide.checkHead = function (position, frame) {
          const elapsed = getTimelineElapsedMs();
          const timeline = window.__livenessTimeline || [];
          const idx = window.__livenessNextAdvanceIdx || 1;
          const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
          const advance = elapsed >= targetMs || elapsed >= getTimelineEndMs();
          const pos = String(position || "CENTER").toUpperCase();
          const isCenter = pos === "CENTER";
          return {
            kind: isCenter ? "all" : "side",
            status: "success",
            passed: advance,
            position: position,
          };
        };
      }
    }

    // Support decider architecture (legacy / alternative AgeSmart)
    if (rc.decider && typeof rc.decider === "object") {
      rc.decider.decide = function (data) {
        if (!window.__livenessRecordStart) resetTimelineRecording();
        const elapsed = getTimelineElapsedMs();
        const timeline = window.__livenessTimeline || [];
        const idx = window.__livenessNextAdvanceIdx || 1;
        const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
        const advance = elapsed >= targetMs || elapsed >= getTimelineEndMs();
        const pos = String(data?.position || "").toLowerCase();
        const isSide = pos.includes("left") || pos.includes("right");
        if (!isSide) {
          return { kind: "all", status: "success", advance };
        }
        return { kind: "side", position: data?.position, status: "success", advance };
      };
    }

    if (typeof rc.goToNextPosition === "function" && !rc.__goNextPatched) {
      rc.__goNextPatched = true;
      const originalGoNext = rc.goToNextPosition.bind(rc);
      rc.goToNextPosition = async function () {
        window.__livenessNextAdvanceIdx = (window.__livenessNextAdvanceIdx || 1) + 1;
        return originalGoNext();
      };
    }

    rc.getAudio = () => ({
      isAudioPlaying: () => false,
      stop: () => {},
      play: () => Promise.resolve(),
    });

    rc.shouldProcessFrame = function () {
      return !this.disposed && !this.showTryAgainUi && !this.isFinished();
    };

    if (typeof rc.onFrame === "function") {
      const oldOnFrame = rc.onFrame.bind(rc);
      rc.onFrame = async function () {
        this.setHasFace(true);
        const vc = this.deps?.visionController;
        if (vc) {
          const engine = vc.get?.();
          if (engine) {
            engine.frame = { hasFace: true, isCenter: true, isLeft: true, isRight: true };
          }
        }
        await oldOnFrame();
      };
    }

    if (typeof rc.initRecordSession === "function") {
      const originalInit = rc.initRecordSession.bind(rc);
      rc.initRecordSession = async function (args) {
        await syncTimelineToVideoStart();
        window.__setVirtualCameraVideo?.(window.__livenessUploadSlot ?? 2);
        try { this.syncFaceLandmarkerReady?.(); } catch (_) {}
        this.setHasFace(true);
        return originalInit(args);
      };
    }

    if (typeof rc.uploadRecordedVideo === "function" && !rc.__uploadSwapPatched) {
      rc.__uploadSwapPatched = true;
      const originalUpload = rc.uploadRecordedVideo.bind(rc);
      rc.uploadRecordedVideo = async function () {
        window.__restoreVirtualCameraLoop?.();
        if (window.__livenessUploadMode !== "file3_swap") {
          return originalUpload.call(this);
        }
        const recorder = typeof this.session?.getRecorder === "function"
          ? this.session.getRecorder()
          : this.session?.recorder;
        if (!recorder) {
          this.recordedUploadFailed?.();
          return;
        }
        await recorder.stop?.();
        const slot = window.__livenessUploadSlot ?? 2;
        const swapFile = await window.__fetchVirtualCameraFile?.(slot);
        if (!swapFile) {
          this.recordedUploadFailed?.();
          return;
        }
        const originalGetBlob = recorder.getBlob?.bind(recorder);
        const originalGetMime = recorder.getRecordedMimeType?.bind(recorder);
        recorder.getBlob = () => swapFile;
        recorder.getRecordedMimeType = () => swapFile.type || "video/mp4";
        try {
          return await originalUpload.call(this);
        } finally {
          if (originalGetBlob) recorder.getBlob = originalGetBlob;
          if (originalGetMime) recorder.getRecordedMimeType = originalGetMime;
        }
      };
    }
  };

  const patchVideoController = (ctrl) => {
    if (!ctrl || ctrl.__nativeAutoPatched) return;
    ctrl.__nativeAutoPatched = true;
    window.__activeVideoController = ctrl;

    ctrl.reloadVideoStep = () => {
      console.warn("[video-step] reloadVideoStep suppressed");
    };

    if (typeof ctrl.showRecordPhase === "function" && !ctrl.__showRecordPhaseWrapped) {
      ctrl.__showRecordPhaseWrapped = true;
      const origShowRecordPhase = ctrl.showRecordPhase.bind(ctrl);
      ctrl.showRecordPhase = function (args) {
        if (args && typeof args === "object") {
          args.onWebcamError = () => console.warn("[video-step] onWebcamError suppressed");
        }
        const res = origShowRecordPhase(args);
        if (ctrl.recordController) {
          patchRecordController(ctrl.recordController);
        }
        return res;
      };
    }

    if (ctrl.faceLandmarker) patchFaceLandmarker(ctrl.faceLandmarker, () => null);
    if (ctrl.visionController) patchVisionController(ctrl.visionController);
    patchInstructionsController(ctrl.instructionsController);
    enableProceedButton();
    if (ctrl.instructionsController?.view) {
      ctrl.instructionsController.view.refreshProceedState?.(false, false);
    }
    if (ctrl.recordController) patchRecordController(ctrl.recordController);
  };

  const hookNativeController = () => {
    if (typeof VerificationWizardVideo === "undefined") return false;

    if (!VerificationWizardVideo.__nativeAutoWrapped) {
      VerificationWizardVideo.__nativeAutoWrapped = true;
      const Original = VerificationWizardVideo.StepVideoController;
      const Wrapped = function (...args) {
        if (args[0] && typeof args[0].steps === "string") {
          args[0].steps = args[0].steps.split(",").map((s) => s.trim().toUpperCase()).join(",");
        }
        const instance = new Original(...args);
        window.__activeVideoController = instance;
        patchVideoController(instance);
        setTimeout(() => {
          if (instance && !instance.instructionsController && !instance.recordController && !instance.submitController) {
            try { instance.start(); } catch (_) {}
          }
        }, 50);
        return instance;
      };
      Wrapped.prototype = Original.prototype;
      VerificationWizardVideo.StepVideoController = Wrapped;

      const proto = Original.prototype;
      if (!proto.__nativeProtoPatched) {
        proto.__nativeProtoPatched = true;
        const wrap = (name, after) => {
          const original = proto[name];
          if (typeof original !== "function") return;
          proto[name] = function (...args) {
            patchVideoController(this);
            const result = original.apply(this, args);
            patchVideoController(this);
            after?.call(this, args, result);
            return result;
          };
        };
        wrap("start");
        wrap("showInstructionsPhase", function () {
          patchInstructionsController(this.instructionsController);
          enableProceedButton();
        });
        wrap("showRecordPhase", function () {
          patchRecordController(this.recordController);
        });
        wrap("showRecord");
        wrap("showSubmitPhase");
      }
    }

    if (window.__activeVideoController) {
      patchVideoController(window.__activeVideoController);
    }
    return true;
  };

  let _vwv = window.VerificationWizardVideo;
  try {
    Object.defineProperty(window, "VerificationWizardVideo", {
      configurable: true,
      enumerable: true,
      get() {
        return _vwv;
      },
      set(val) {
        _vwv = val;
        try {
          hookNativeController();
        } catch (e) {
          console.warn("[video-step] hook on set error:", e);
        }
      },
    });
  } catch (e) {
    console.warn("[video-step] defineProperty error:", e);
  }
  if (_vwv) {
    hookNativeController();
  }

  const checkSubmitResult = () => {
    const modalHost = document.getElementById("wizard-layout-modal-backend-host");
    if (modalHost) {
      const style = window.getComputedStyle(modalHost);
      if (style.display !== "none" && style.visibility !== "hidden") {
        const message = document.getElementById("wizard-backend-error-message");
        return {
          status: "error",
          message: (message?.textContent || "Submission failed").trim(),
        };
      }
    }
    const url = window.location.href.toLowerCase();
    const fail = ["/fail", "/failed", "/rejected", "/declined", "/error", "/denied"];
    if (fail.some((part) => url.includes(part))) {
      return { status: "error", message: "Verification failed", url: window.location.href };
    }
    const ok = ["/success", "/complete", "/approved", "/accepted", "/passed", "/verified", "/thank"];
    if (ok.some((part) => url.includes(part))) {
      return { status: "success", url: window.location.href };
    }
    if (!url.includes("/verification/video/")) {
      return { status: "success", url: window.location.href };
    }
    return { status: "pending" };
  };

  // Native cascade driver — one tick per Python poll.
  window.__videoStepAutopilot = {
    proceeded: false,
    submitted: false,

    tick() {
      hookNativeController();
      const phase = detectPhase();
      const ctrl = window.__activeVideoController;
      const rc = ctrl?.recordController;

      if (ctrl && !ctrl.instructionsController && !ctrl.recordController && !ctrl.submitController) {
        try { ctrl.start(); } catch (e) { console.warn("[video-step] ctrl.start() error", e); }
      }

      if (phase === "instructions" || phase === "unknown") {
        patchInstructionsController(ctrl?.instructionsController);
        enableProceedButton();
        window.__setVirtualCameraVideo?.(window.__livenessUploadSlot ?? 2);
      }

      if (phase === "instructions" || phase === "unknown") {
        if (ctrl?.showRecord) {
          try {
            ctrl.showRecord();
            this.proceeded = true;
            resetTimelineRecording();
            return { phase: "record", action: "showRecord", ok: true };
          } catch (err) {
            console.warn("[video-step] showRecord failed", err);
          }
        }
        const btn = document.getElementById(BTN.PROCEED);
        if (btn) {
          btn.disabled = false;
          btn.removeAttribute("disabled");
          btn.click();
          return { phase: "instructions", action: "proceed-click", ok: true };
        }
      }

      if (phase === "record") {
        if (rc) patchRecordController(rc);
        window.__setVirtualCameraVideo?.(window.__livenessUploadSlot ?? 2);
        if (!window.__livenessRecordStart) resetTimelineRecording();
        try { rc?.setHasFace?.(true); } catch (_) {}
        if (rc) rc.hasFace = true;

        // Autopilot auto-advance: if elapsed time reaches target timeline mark, advance step
        if (rc && !rc.isFinished?.() && !rc.stepLocked && !rc.disposed && !rc.showTryAgainUi) {
          const elapsed = getTimelineElapsedMs();
          const timeline = window.__livenessTimeline || [];
          const idx = window.__livenessNextAdvanceIdx || 1;
          const targetMs = timeline[idx]?.startMs ?? getTimelineEndMs();
          if (elapsed >= targetMs && typeof rc.goToNextPosition === "function") {
            rc.goToNextPosition().catch((e) => console.warn("[video-step] auto advance failed", e));
          }
        }

        // Auto-upload trigger: when all steps are completed, ensure uploadRecordedVideo is scheduled
        if (rc && rc.isFinished?.() && !rc.showTryAgainUi && !rc.disposed) {
          if (!rc.__autoUploadScheduled && typeof rc.uploadRecordedVideo === "function") {
            rc.__autoUploadScheduled = true;
            setTimeout(() => {
              if (rc && !rc.disposed && !rc.showTryAgainUi) {
                rc.uploadRecordedVideo().catch((e) => console.warn("[video-step] auto upload failed", e));
              }
            }, 1200);
          }
        }

        // Auto-recover if site shows try-again UI
        if (rc && rc.showTryAgainUi) {
          rc.setShowTryAgainUi?.(false);
          rc.retryFromStart?.().catch(() => {});
        }
      }

      if (phase === "submit" && !this.submitted) {
        const submitCtrl = ctrl?.submitController;
        if (submitCtrl?.submit) {
          this.submitted = true;
          submitCtrl.submit().catch((err) => console.warn("[video-step] submit failed", err));
          return { phase: "submit", action: "submit-controller", ok: true };
        }
        const btn = document.getElementById(BTN.SUBMIT);
        if (btn && !btn.disabled) {
          btn.click();
          this.submitted = true;
          return { phase: "submit", action: "submit-click", ok: true };
        }
      }

      const result = checkSubmitResult();
      if (result.status === "success") {
        return { phase, result: "success", url: result.url, ok: true };
      }
      if (result.status === "error") {
        return { phase, result: "error", message: result.message, ok: false };
      }

      const elapsed = getTimelineElapsedMs();
      const endMs = getTimelineEndMs();
      return {
        phase,
        proceeded: this.proceeded,
        submitted: this.submitted,
        recording: Boolean(rc && !rc.isFinished?.()),
        finished: Boolean(rc?.isFinished?.()),
        elapsedMs: elapsed,
        endMs,
        ok: true,
      };
    },
  };

  hookNativeController();
})();
